import React from "react";
import classes from "./Dialogs.module.css";
import DialogItem from "./dialog-item-component/DialogItem";
import MessagesItem from "./messages-item-component/MessagesItem";
import { Field, reduxForm } from "redux-form";
import { Textarea } from "../../commons/formControls/formsControl";
import {
  maxLengthCreatore,
  requiredField,
} from "../../../utils/validators/validators";

const maxLength100 = maxLengthCreatore(100);

const Dialogs = (props) => {
  let messageItems = props.stateMesaages.messages.map((m) => {
    return <MessagesItem message={m.message} key={m.id} />;
  });

  let dialogItems = props.stateMesaages.dialogs.map((d) => {
    return <DialogItem name={d.name} id={d.id} key={d.id} />;
  });

  let addNewMessage = (v) => {
    props.addMessage(v.newMessageText);
  };

  return (
    <div className={classes.dialogs}>
      <aside className={classes.sidebar}>
        <div className="pageEyebrow">Inbox</div>
        <h2 className="pageTitle" style={{ fontSize: 22, marginBottom: 14 }}>
          Сообщения
        </h2>
        <div className={classes.dialogsItems}>{dialogItems}</div>
      </aside>

      <section className={classes.chat}>
        <div className={classes.chatHeader}>
          <div className="feedAuthor">Диалог</div>
          <div className="feedTime">демо-чат без вебсокетов</div>
        </div>
        <div className={classes.messages}>
          {messageItems.length ? (
            messageItems
          ) : (
            <div className="emptyState">
              <strong>Пока тихо</strong>
              Напиши первое сообщение справа внизу
            </div>
          )}
        </div>
        <div className={classes.composer}>
          <AddMessageFormRedux onSubmit={addNewMessage} />
        </div>
      </section>
    </div>
  );
};

const AddMessageForm = (props) => {
  return (
    <form onSubmit={props.handleSubmit}>
      <Field
        component={Textarea}
        name="newMessageText"
        placeholder="Написать сообщение..."
        validate={[requiredField, maxLength100]}
      />
      <button type="submit">Отправить</button>
    </form>
  );
};

const AddMessageFormRedux = reduxForm({ form: "dialogAddMessageForm" })(
  AddMessageForm
);

export default Dialogs;
